body.query:
query TaxonKey($key: ID!, $datasetKey: ID!, $language: String, $colDatasetKey: ID!) {
  taxonInfo(key: $key, datasetKey: $datasetKey) {
    group: taxonomicGroup
    checklistbankURL
    groupIconSVG
    datasetKey
    taxonID
    taxonRank
    scientificName
    taxonomicStatus
    label
    references
    acceptedNameUsageID
    acceptedTaxon {
      taxonID
      label
      scientificName
    }
    occurrenceMedia(limit: 20) {
      count
      results {
        occurrenceKey
        identifier
        license
        rightsHolder
        thumbor(height: 800)
      }
    }
    treatments: related(datasetType: ARTICLE) {
      taxonID
      datasetKey
      references
    }
    relatedColEntries: related(datasetKey: [$colDatasetKey]) {
      taxonID
    }
    relatedInfo {
      griis {
        datasetKey
        taxonID
        locality
        countryCode
        isInvasive
        isCountry
      }
      redlist {
        taxonID
        scientificName
        threatStatus
        references
      }
    }
    synonyms {
      homotypic {
        taxonID
        label
        isOriginalNameUsage
      }
      heterotypic {
        taxonID
        label
        isOriginalNameUsage
      }
    }
    media {
      identifier
      title
      references
      type
      creator
      license
    }
    vernacularNames {
      vernacularName
      language
    }
    bibliography {
      referenceID
      doi
      url
      citation
      remarks
      isNamePublishedIn
    }
    vernacularName(language: $language) {
      vernacularName
    }
    classification {
      taxonID
      scientificName
      scientificNameAuthorship
      taxonRank
    }
  }
}
